def comps_of(g):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            x,y=a+di,b+dj
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==g[i][j] and (x,y) not in seen:
                                seen.add((x,y)); st.append((x,y))
                out.append((g[i][j],comp))
    return sorted(out,key=lambda t:t[1])
