import numpy as np
def comps(g):
    from collections import deque
    g=np.array(g); H,W=g.shape; seen=np.zeros((H,W),bool); out=[]
    for i in range(H):
        for j in range(W):
            if g[i,j] and not seen[i,j]:
                col=g[i,j]; q=deque([(i,j)]); seen[i,j]=True; pts=[]
                while q:
                    y,x=q.popleft(); pts.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            yy,xx=y+dy,x+dx
                            if 0<=yy<H and 0<=xx<W and g[yy,xx]==col and not seen[yy,xx]:
                                seen[yy,xx]=True; q.append((yy,xx))
                out.append((col,pts))
    return out
