# Band order (fits all 4 demos): fewer DISTINCT component shapes first; tie -> larger total pixel count first.
def f(ci):
    g=np.array(ci); H=len(ci); W=len(ci[0])
    comps=comps4(g)
    groups=collections.defaultdict(list)
    for c,pnts in comps: groups[c].append(pnts)
    def nshapes(c):
        ss=set()
        for pnts in groups[c]:
            ys=[y for y,x in pnts]; xs=[x for y,x in pnts]
            ss.add(frozenset((y-min(ys),x-min(xs)) for y,x in pnts))
        return len(ss)
    colorder=sorted(groups,key=lambda c:(nshapes(c), -sum(len(p) for p in groups[c])))
    out=[[0]*W for _ in range(H)]
    curx=0
    for c in colorder:
        Ps=groups[c]
        # sort comps by size asc (smallest on top)
        Ps.sort(key=len)
        bw=max(max(x for y,x in p)-min(x for y,x in p)+1 for p in Ps)
        lev=H-1
        for pts in reversed(Ps):
            ys=[y for y,x in pts]; xs=[x for y,x in pts]
            h=max(ys)-min(ys)+1; top=lev-h+1
            for yy,xx in pts:
                oy,ox=yy-min(ys),xx-min(xs)
                out[top+oy][curx+ox]=c
            lev=top-2
        curx+=bw+1
    return out

