def f(gin):
    gi=np.array(gin); H,W=gi.shape
    cc=comps_of(gi)
    # band order: color with smaller min component size first; tie -> larger total first
    bycolor=collections.defaultdict(list)
    for c,ps in cc: bycolor[c].append(ps)
    def key(c):
        szs=[len(q) for qq,q in bycolor[c]]
        return (min(szs), -sum(szs))
    order=sorted(bycolor, key=key)
    canvas=np.zeros((H,W),dtype=int)
    # place bands left to right, packed: next start = prev start + prev max-width + 1
    pos=0; mx=0
    for c in order:
        comps=sorted(bycolor[c], key=lambda ps:(-len(ps), min(y for y,_ in ps)))
        w=max(max(x for _,x in q)-min(x for _,x in q)+1 for q in comps)
        if pos+mx+1>W: pos=0; mx=0  # safety reset
        for rank,ps in enumerate(comps):
            h=max(y for y,_ in ps)-min(y for y,_ in ps)+1
            ty = H-h if rank==0 else (comps[rank-1][0] - h -1) if False else None
        # anchor: bottom-most comp (largest) at bottom; others stack up with 1-row gap
        for idx,ps in enumerate(comps):
            hh=max(y for y,_ in ps)-min(y for y,_ in ps)+1
            if idx==len(comps)-1:
                t=H-hh
            else:
                prev=comps[idx+1]
                th=max(y for y,_ in prev)-min(y for y,_ in prev)+1
                t= (H-th) - hh - 1
            for (y,x) in ps:
                canvas[t+y-min(y for y,_ in ps), pos+x-min(x for _,x in ps)]=c
        mx=max(mx,w); pos=pos+w+1
    return canvas.tolist()

