# Hypothesis: pieces fall down (gravity), processed bottom-up by initial position; stacking allowed on other pieces / floor.
def gravity(g, order=None):
    g=np.array(g); H,W=g.shape
    comps=cc(g)
    if order is None:
        # sort by bottom-most first, then right-most first
        def key(c_): h=max(p[0] for p in c_[1])
        order=sorted(range(len(comps)),key=lambda i:(-max(p[0] for p in comps[i][1]), -max(p[1] for p in comps[i][1])))
    canvas=np.full((H,W),0)
    placed=[]
    for idx in order:
        c_,pts=comps[idx]; pts=list(pts)
        moved=True
        while moved:
            moved=False
            for (y,x) in pts:
                n=(y+1,x)
                if y+1<H and canvas[n[0],n[1]]==0:
                    pts[pts.index((y,x))]=(y+1,x); moved=True; break
        for y,x in pts: canvas[y,x]=c_
        placed.append(pts)
    return canvas
