def solve(gin):
    g=np.array(gin); H,W=g.shape
    comps=[(c,set(p)) for c,p in cc(g)]
    # color groups sorted by max bottom row desc, tie scan order
    def botmax(c):
        pcs=[p for cc_,p in comps if cc_==c]
        return max(max(y for y,_ in p) for p in pcs)
    orders=sorted(set(c for c,_ in comps), key=lambda c:(-botmax(c)))
    used=set(); out=[[0]*W for _ in range(H)]
    for c in orders:
        pcs=[p for cc_,p in comps if cc_==c]
        pcs.sort(key=lambda p:(len(p), -min(y for y,_ in p)))  # size asc then top-most desc? check on demos
        cx=0
        while True:
            cand=[{(ty+a,cx+b) for ty,a,b in []}] 
            placed_ok=True
            for p in pcs:
                cells={(y+a+ (cx - min(x2 for _,x2 in p)), x+b+(cx-min(x2 for _,x2 in p))) for y,x in p}
                # wait simpler: shift whole comp so its leftmost column goes to cx
                offs=min(x2 for _,x2 in p)
                cells={(y+a+ (cx-offs), x+b+(cx-offs)) for y,x in p}
                if any(out[y][x]!=0 or (y,x) in used for y,x in cells): placed_ok=False; break
                if any(((y+dy),(x+dx)) in {(Y,X) for Y,X in [(y,dx)]} for y,x in cells): pass
            if placed_ok:
                for p in pcs:
                    offs=min(x2 for _,x2 in p)
                    for y,x in p: out[y+(cx-offs)][x+(cx-offs)]=c
                used|={ (y,x) for p in pcs for y,x in p for y,x in [(y,x)]}
                # mark used cells of THIS placement including future placements -> use actual coords
                used |= {(y+(cx-offs), x+(cx-offs)) for p in pcs for y,x in p}
                break
            cx+=1
            if cx>=W: print('fail'); break
    return out
